-- Chalk and Iron, Phase 1: bring existing accounts up to starter library version 2.
-- Approved by Nathan on 17 November 2026: every account gets the 227-exercise
-- library from the outside coach's review (data/starter-library.json, version 2),
-- with 14 rest times made consistent with the default rule.
--
-- Plain-language summary for Nathan:
--   * New accounts already get version 2 from the data file. This brings
--     accounts made before then, which have the first 42, up to the same 227.
--   * The coach's edits to the first 42 (new swaps, notes, the leg press now
--     named "Angled Leg Press", the reverse curl filed under Biceps) are made
--     only where that detail is still as the app first set it. Anything you
--     changed yourself is left alone.
--   * The new exercises are added, except any whose name is already in the
--     account, archived ones included, so nothing archived comes back and no
--     near-duplicate is made.
--   * Swaps are then linked to the exercise of the same name, so a swap uses
--     that exercise's own history.
--   * Nothing is deleted. It is safe to run more than once: a second run
--     changes nothing. It ends by showing what it did for each account.

begin;

-- Copy of src/rules/names.ts: a name reduced to its sorted words.
create or replace function pg_temp.name_key(input text)
returns text language sql immutable strict as $fn$
  with words(word) as (
    select regexp_split_to_table(regexp_replace(lower(input), '[^a-z0-9]+', ' ', 'g'), ' +')
  ), singular(word) as (
    select case
      when length(word) > 3 and word ~ 'ies$' then left(word, -3) || 'y'
      when length(word) > 3 and word ~ '(ss|sh|ch|x)es$' then left(word, -2)
      when length(word) > 3 and word ~ '[^s]s$' then left(word, -1)
      else word
    end
    from words
    where word <> ''
  )
  select coalesce(string_agg(parts.word, ' ' order by parts.word collate "C"), '')
  from singular
  cross join lateral regexp_split_to_table(case singular.word
    when 'db' then 'dumbbell' when 'dbs' then 'dumbbell' when 'bb' then 'barbell'
    when 'kb' then 'kettlebell' when 'bw' then 'bodyweight' when 'ohp' then 'overhead press'
    when 'rdl' then 'romanian deadlift' when 'pushup' then 'push up' when 'pullup' then 'pull up'
    when 'chinup' then 'chin up' when 'situp' then 'sit up' when 'selectorised' then 'selectorized'
    else singular.word
  end, ' ') as parts(word)
  where parts.word <> '';
$fn$;

create temp table starter_v2_report (account text, edited integer, added integer, linked integer) on commit drop;

-- Keep other exercise edits out while this runs.
lock table public.exercises in share row exclusive mode;

do $do$
