"focus":null,"equipment":"dumbbell","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Step sideways and sit back over the working leg.","alternates":{"bodyweight":"Bodyweight Side-Lying Adduction","basic_gym":"Band Hip Adduction","full_gym":"Selectorized Machine Hip Adduction"}},{"name":"Band Hip Adduction","muscle_group":"Adductors","focus":null,"equipment":"band","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Anchor the band to the side and draw your working leg inward.","alternates":{"bodyweight":"Bodyweight Side-Lying Adduction","basic_gym":"Dumbbell Lateral Lunge","full_gym":"Cable Standing Hip Adduction"}},{"name":"Cable Standing Hip Adduction","muscle_group":"Adductors","focus":null,"equipment":"cable","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Sweep the cuffed leg inward without turning your hips.","alternates":{"bodyweight":"Bodyweight Side-Lying Adduction","basic_gym":"Dumbbell Lateral Lunge","full_gym":"Selectorized Machine Hip Adduction"}},{"name":"Band Standing Hip Abduction","muscle_group":"Abductors","focus":null,"equipment":"band","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Keep your trunk still as your leg moves out.","alternates":{"bodyweight":"Bodyweight Side-Lying Leg Raise","basic_gym":"Band Lateral Walk","full_gym":"Selectorized Machine Hip Abduction"}},{"name":"Plate-Loaded Machine Sled Push","muscle_group":"Quads","focus":null,"equipment":"plate-loaded machine","default_unit":"lb","work_seconds":45,"rest_seconds":120,"note":"Log the added plates. Count one fixed-distance trip as one rep and keep the distance and surface consistent.","alternates":{"bodyweight":"Bodyweight Step-Up","basic_gym":"Dumbbell Walking Lunge","full_gym":"Plate-Loaded Machine Sled Backward Drag"}},{"name":"Plate-Loaded Machine Sled Backward Drag","muscle_group":"Quads","focus":null,"equipment":"plate-loaded machine","default_unit":"lb","work_seconds":45,"rest_seconds":120,"note":"Hold the sled handles or tow strap and walk backward. Count one fixed-distance trip as one rep.","alternates":{"bodyweight":"Bodyweight Reverse Lunge","basic_gym":"Dumbbell Reverse Lunge","full_gym":"Plate-Loaded Machine Sled Push"}},{"name":"Plate-Loaded Machine Sled Hand-Over-Hand Rope Pull","muscle_group":"Back","focus":"upper back","equipment":"plate-loaded machine","default_unit":"lb","work_seconds":45,"rest_seconds":120,"note":"Stay in place and pull the sled toward you hand over hand. Count one fixed-distance pull as one rep.","alternates":{"bodyweight":"Bodyweight Inverted Row","basic_gym":"Dumbbell One-Arm Row","full_gym":"Cable Seated Row"}},{"name":"Plate-Loaded Machine Standing Leg Curl","muscle_group":"Hamstrings","focus":null,"equipment":"plate-loaded machine","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Line up your knee with the machine pivot and log reps per side.","alternates":{"bodyweight":"Bodyweight Sliding Leg Curl","basic_gym":"Band Lying Leg Curl","full_gym":"Selectorized Machine Standing Leg Curl"}},{"name":"Selectorized Machine Standing Leg Curl","muscle_group":"Hamstrings","focus":null,"equipment":"selectorized machine","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Record the stack setting and log reps per side.","alternates":{"bodyweight":"Bodyweight Sliding Leg Curl","basic_gym":"Band Lying Leg Curl","full_gym":"Plate-Loaded Machine Standing Leg Curl"}},{"name":"Selectorized Machine Triceps Pushdown","muscle_group":"Triceps","focus":"lateral head","equipment":"selectorized machine","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Keep your torso steady and press the handles down through a comfortable range.","alternates":{"bodyweight":"Bodyweight Bar Triceps Extension","basic_gym":"Band Pushdown","full_gym":"Cable Straight-Bar Pushdown"}},{"name":"Bodyweight Box Jump","muscle_group":"Quads","focus":null,"equipment":"bodyweight","default_unit":"bw","work_seconds":45,"rest_seconds":120,"note":"Jump onto a stable platform, land softly, and step down. Record reps and keep track of platform height.","alternates":{"bodyweight":"Bodyweight Step-Up","basic_gym":"Kettlebell Swing","full_gym":"Plate-Loaded Machine Hack Squat"}},{"name":"Barbell EZ-Bar Curl","muscle_group":"Biceps","focus":"short head","equipment":"barbell","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Use the angled grips on the EZ bar and keep your upper arms steady.","alternates":{"bodyweight":"Bodyweight Chin-Up","basic_gym":"Barbell Curl","full_gym":"Cable Curl"}},{"name":"Dumbbell Zottman Curl","muscle_group":"Biceps","focus":"brachialis","equipment":"dumbbell","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Curl palms up, turn your forearms palms down at the top, and lower under control. Turn palms up again at the bottom.","alternates":{"bodyweight":"Bodyweight Neutral-Grip Pull-Up","basic_gym":"Dumbbell Reverse Curl","full_gym":"Cable Reverse Curl"}},{"name":"Cable Seated Shoulder Press","muscle_group":"Shoulders","focus":"front","equipment":"cable","default_unit":"lb","work_seconds":45,"rest_seconds":120,"note":"Sit between two low pulleys. Start with the handles near shoulder height and press overhead.","alternates":{"bodyweight":"Bodyweight Pike Push-Up","basic_gym":"Dumbbell Seated Shoulder Press","full_gym":"Selectorized Machine Shoulder Press"}},{"name":"Cable Seated Chest Press","muscle_group":"Chest","focus":"mid","equipment":"cable","default_unit":"lb","work_seconds":45,"rest_seconds":120,"note":"Sit facing away from the pulleys. Start with the handles at chest height and press forward.","alternates":{"bodyweight":"Bodyweight Push-Up","basic_gym":"Dumbbell Bench Press","full_gym":"Selectorized Machine Chest Press"}},{"name":"Cable Seated Curl","muscle_group":"Biceps","focus":"short head","equipment":"cable","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Sit facing a low pulley and curl with your palms up. Keep your upper arms steady.","alternates":{"bodyweight":"Bodyweight Chin-Up","basic_gym":"Dumbbell Alternating Curl","full_gym":"Cable Curl"}},{"name":"Selectorized Machine Lateral Raise","muscle_group":"Shoulders","focus":"side","equipment":"selectorized machine","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Set the pads or handles to a comfortable starting position. Raise your arms out to the sides.","alternates":{"bodyweight":"Bodyweight Side-Lying Lateral Raise","basic_gym":"Dumbbell Lateral Raise","full_gym":"Selectorized Machine Standing Lateral Raise"}},{"name":"Selectorized Machine Standing Lateral Raise","muscle_group":"Shoulders","focus":"side","equipment":"selectorized machine","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Stand tall and raise the handles out to the sides. Lower under control.","alternates":{"bodyweight":"Bodyweight Side-Lying Lateral Raise","basic_gym":"Dumbbell Lateral Raise","full_gym":"Selectorized Machine Lateral Raise"}},{"name":"Selectorized Machine Standing Shoulder Adduction","muscle_group":"Back","focus":"lats","equipment":"selectorized machine","default_unit":"lb","work_seconds":45,"rest_seconds":90,"note":"Start with your arms out to the sides. Keep a soft bend in your elbows and sweep the handles down in an arc toward your hips.","alternates":{"bodyweight":"Bodyweight Pull-Up","basic_gym":"Band Lat Pulldown","full_gym":"Cable Straight-Arm Pulldown"}}]$starter$::jsonb;
  p record;
  pr jsonb;
  o jsonb;
  nw jsonb;
  ex jsonb;
  x public.exercises;
  t text;
  old_mg uuid; old_fo uuid; old_eq uuid; new_mg uuid; new_fo uuid; new_eq uuid;
  n_edit integer; n_add integer; n_link integer; k integer;
  new_id uuid;
  v_name text; v_mg uuid; v_fo uuid; v_eq uuid; v_unit text; v_work integer; v_rest integer; v_note text;
begin
  for p in select id, display_name from public.profiles order by created_at loop
    n_edit := 0; n_add := 0; n_link := 0;

    -- 1. The coach's edits to the first 42, field by field, only where unchanged.
    for pr in select * from jsonb_array_elements(pairs) loop
      o := pr -> 'old'; nw := pr -> 'new';
      select * into x from public.exercises
       where user_id = p.id and archived_at is null and lower(name) = lower(o ->> 'name') limit 1;
      if not found then continue; end if;

      select id into old_mg from public.vocabulary_terms where user_id = p.id and kind = 'muscle_group' and lower(name) = lower(o ->> 'muscle_group');
      select id into old_fo from public.vocabulary_terms where user_id = p.id and kind = 'focus' and parent_id = old_mg and lower(name) = lower(o ->> 'focus');
      select id into old_eq from public.vocabulary_terms where user_id = p.id and kind = 'equipment' and lower(name) = lower(o ->> 'equipment');
      select id into new_mg from public.vocabulary_terms where user_id = p.id and kind = 'muscle_group' and archived_at is null and lower(name) = lower(nw ->> 'muscle_group');
      select id into new_fo from public.vocabulary_terms where user_id = p.id and kind = 'focus' and archived_at is null and parent_id = new_mg and lower(name) = lower(nw ->> 'focus');
      select id into new_eq from public.vocabulary_terms where user_id = p.id and kind = 'equipment' and archived_at is null and lower(name) = lower(nw ->> 'equipment');

      v_name := x.name; v_mg := x.muscle_group_id; v_fo := x.focus_id; v_eq := x.equipment_id;
      v_unit := x.default_unit; v_work := x.work_seconds; v_rest := x.rest_seconds; v_note := x.note;
      if nw ->> 'name' <> o ->> 'name' and not exists (
           select 1 from public.exercises d where d.user_id = p.id and d.id <> x.id
              and pg_temp.name_key(d.name) = pg_temp.name_key(nw ->> 'name')) then
        v_name := nw ->> 'name';
      end if;
      if x.muscle_group_id is not distinct from old_mg and x.focus_id is not distinct from old_fo
         and new_mg is not null and (nw ->> 'focus' is null or new_fo is not null) then
        v_mg := new_mg; v_fo := new_fo;
      end if;
      if x.equipment_id is not distinct from old_eq and new_eq is not null then v_eq := new_eq; end if;
      if x.default_unit = o ->> 'default_unit' then v_unit := nw ->> 'default_unit'; end if;
      if x.work_seconds = (o ->> 'work_seconds')::integer then v_work := (nw ->> 'work_seconds')::integer; end if;
      if x.rest_seconds = (o ->> 'rest_seconds')::integer then v_rest := (nw ->> 'rest_seconds')::integer; end if;
      if x.note = coalesce(o ->> 'note', '') then v_note := coalesce(nw ->> 'note', ''); end if;
      if (v_name, v_mg, v_fo, v_eq, v_unit, v_work, v_rest, v_note) is distinct from
         (x.name, x.muscle_group_id, x.focus_id, x.equipment_id, x.default_unit, x.work_seconds, x.rest_seconds, x.note) then
        update public.exercises
           set name = v_name, muscle_group_id = v_mg, focus_id = v_fo, equipment_id = v_eq,
               default_unit = v_unit, work_seconds = v_work, rest_seconds = v_rest, note = v_note
         where id = x.id;
        n_edit := n_edit + 1;
      end if;

      foreach t in array array['bodyweight', 'basic_gym', 'full_gym'] loop
        update public.exercise_alternates a
           set name = nw -> 'alternates' ->> t, alternate_exercise_id = null
         where a.exercise_id = x.id and a.tier = t
           and a.name = o -> 'alternates' ->> t
           and a.name <> nw -> 'alternates' ->> t;
        get diagnostics k = row_count;
        n_edit := n_edit + k;
      end loop;
    end loop;

    -- 2. Add the new exercises, skipping any name already in the account.
    for ex in select * from jsonb_array_elements(library) loop
      if exists (select 1 from public.exercises d where d.user_id = p.id
                 and pg_temp.name_key(d.name) = pg_temp.name_key(ex ->> 'name')) then
        continue;
      end if;
      new_id := null;
      insert into public.exercises (user_id, name, muscle_group_id, focus_id, equipment_id, default_unit,
                                    work_seconds, rest_seconds, note, created_via)
      select p.id, ex ->> 'name', g.id, fo.id, e.id, ex ->> 'default_unit',
             (ex ->> 'work_seconds')::integer, (ex ->> 'rest_seconds')::integer, coalesce(ex ->> 'note', ''), 'starter'
      from public.vocabulary_terms g
      left join public.vocabulary_terms fo on fo.user_id = p.id and fo.kind = 'focus' and fo.parent_id = g.id
                                           and fo.archived_at is null and lower(fo.name) = lower(ex ->> 'focus')
      join public.vocabulary_terms e on e.user_id = p.id and e.kind = 'equipment' and e.archived_at is null
                                     and lower(e.name) = lower(ex ->> 'equipment')
      where g.user_id = p.id and g.kind = 'muscle_group' and g.archived_at is null
        and lower(g.name) = lower(ex ->> 'muscle_group')
        and (ex ->> 'focus' is null or fo.id is not null)
      returning id into new_id;
      if new_id is null then continue; end if;  -- the account archived a term this exercise needs
      n_add := n_add + 1;
      foreach t in array array['bodyweight', 'basic_gym', 'full_gym'] loop
        insert into public.exercise_alternates (user_id, exercise_id, tier, name)
        values (p.id, new_id, t, ex -> 'alternates' ->> t);
      end loop;
    end loop;

    -- 3. Link every unlinked swap to the live exercise of the same name.
    update public.exercise_alternates a
       set alternate_exercise_id = (
         select d.id from public.exercises d
          where d.user_id = a.user_id and d.archived_at is null and d.id <> a.exercise_id
            and pg_temp.name_key(d.name) = pg_temp.name_key(a.name)
          order by (lower(d.name) = lower(a.name)) desc, d.created_at
          limit 1)
     where a.user_id = p.id and a.alternate_exercise_id is null
       and exists (
         select 1 from public.exercises d
          where d.user_id = a.user_id and d.archived_at is null and d.id <> a.exercise_id
            and pg_temp.name_key(d.name) = pg_temp.name_key(a.name));
    get diagnostics n_link = row_count;

    insert into starter_v2_report values (p.display_name, n_edit, n_add, n_link);
  end loop;
end
$do$;

select account, edited as "details updated", added as "exercises added", linked as "swaps linked"
from starter_v2_report;

drop function pg_temp.name_key(text);
commit;
